def ls_rows(out):
    """{key: (open, done, oldest)} from the table body of cmd_ls."""
    lines = out.splitlines()
    body = lines[2:lines.index("-" * 74, 2)]
    rows = {}
    for line in body:
        key, open_, done, oldest = line.split()
        rows[key] = (int(open_), int(done), oldest)
    return rows, [line.split()[0] for line in body]


class LoadTests(BacklogTestCase):
    def test_missing_index_exits_telling_how_to_build_it(self):
        with mock.patch.object(sys, "argv", ["/opt/bin/backlog"]):
            msg, _o, _e = self.exit_message(self.mod.load)
        self.assertEqual("no index yet — run: /opt/bin/backlog sync", msg)

    def test_blank_lines_are_skipped_and_missing_meta_is_empty(self):
        os.makedirs(self.zuvo)
        with open(self.mod.INDEX, "w") as f:
            f.write('{"item_id": "B-1"}\n\n   \n{"item_id": "B-2"}\n')
        items, meta = self.mod.load()
        self.assertEqual([{"item_id": "B-1"}, {"item_id": "B-2"}], items)
        self.assertEqual({}, meta)

    def test_meta_is_returned_when_present(self):
        self.write_index([item("h", "r", "B-1")], meta={"hosts": {"h": {"run_id": "r1"}}, "strays": []})
        items, meta = self.mod.load()
        self.assertEqual(["B-1"], [i["item_id"] for i in items])
        self.assertEqual({"hosts": {"h": {"run_id": "r1"}}, "strays": []}, meta)


class CmdLsTests(BacklogTestCase):
    def test_counts_per_short_host_and_repo_sorted_by_open_desc_with_total(self):
        self.write_index([
            item("mac.local", "zuvo", "Z-1", "open", added="2026-01-05"),
            item("mac.local", "zuvo", "Z-2", "open", added="2026-01-02"),
            item("mac.local", "zuvo", "Z-3", "open", added="2026-01-09"),
            item("mac.local", "zuvo", "Z-4", "done", added=""),
            item("vps", "api", "A-1", "done", added="2026-03-01"),
            item("vps", "api", "A-2", "open", added=""),
            item("vps", "api", "A-3", "done", added="2026-02-01"),
            item("bot.example.com", "site", "S-1", "open", added="2026-04-04"),
            item("bot.example.com", "site", "S-2", "open"),
        ], meta={"hosts": {"mac.local": {}, "vps": {}, "bot.example.com": {}, "gone": {}}})
        _r, out, _e = self.capture(self.mod.cmd_ls)
        rows, order = ls_rows(out)
        self.assertEqual({"mac:zuvo": (3, 1, "2026-01-02"),
                          "bot:site": (2, 0, "2026-04-04"),
                          "vps:api": (1, 2, "2026-02-01")}, rows)
        self.assertEqual(["mac:zuvo", "bot:site", "vps:api"], order)
        self.assertEqual("TOTAL open=6 done=3 across 3 repos / 4 hosts", out.splitlines()[-1])
        self.assertEqual(f"{'repo':<46} {'open':>6} {'done':>6}  oldest", out.splitlines()[0])

    def test_oldest_ignores_empty_dates_seen_first(self):
        self.write_index([item("h", "r", "1", added=""), item("h", "r", "2", added="2026-05-05"),
                          item("h", "r", "3", added="")])
        _r, out, _e = self.capture(self.mod.cmd_ls)
        self.assertEqual({"h:r": (3, 0, "2026-05-05")}, ls_rows(out)[0])

    def test_oldest_with_no_dates_prints_a_dash(self):
        self.write_index([item("h", "r", "1", added=""), {"host": "h", "repo": "r", "status": "done"}])
        _r, out, _e = self.capture(self.mod.cmd_ls)
        self.assertEqual({"h:r": (1, 1, "-")}, ls_rows(out)[0])

    def test_equal_oldest_dates_keep_the_value(self):
        self.write_index([item("h", "r", "1", added="2026-01-01"), item("h", "r", "2", added="2026-01-01")])
        _r, out, _e = self.capture(self.mod.cmd_ls)
        self.assertEqual({"h:r": (2, 0, "2026-01-01")}, ls_rows(out)[0])

    def test_missing_status_counts_as_open_and_other_statuses_are_not_open_or_done(self):
        self.write_index([{"host": "h", "repo": "r"}, item("h", "r", "2", status="wontfix")], meta={})
        _r, out, _e = self.capture(self.mod.cmd_ls)
        self.assertEqual({"h:r": (1, 0, "-")}, ls_rows(out)[0])
        self.assertEqual("TOTAL open=1 done=0 across 1 repos / 0 hosts", out.splitlines()[-1])

    def test_missing_host_and_repo_show_question_marks(self):
        self.write_index([{"status": "open"}])
        _r, out, _e = self.capture(self.mod.cmd_ls)
        self.assertEqual({"?:?": (1, 0, "-")}, ls_rows(out)[0])

    def test_long_keys_are_cut_to_45_characters(self):
        repo = "r" * 60
        self.write_index([item("h", repo, "1")])
        _r, out, _e = self.capture(self.mod.cmd_ls)
        self.assertEqual([("h:" + repo)[:45]], ls_rows(out)[1])


class CmdOpenTests(BacklogTestCase):
    def setUp(self):
        super().setUp()
        self.write_index([
            item("mac.local", "zuvo-plugin", "B-1", "open", "high", "2026-01-01", "first"),
            item("mac.local", "zuvo-plugin", "B-2", "open", None, "2026-03-01", "newest"),
            item("vps", "other", "O-1", "open", "low", "", "undated"),
            item("vps", "zuvo-landing", "L-1", "done", "critical", "2026-04-01", "closed"),
            item("vps", "zuvo-landing", "L-2", "open", "medium", "2026-02-01", "landing"),
        ])

    def test_only_open_items_newest_first_undated_last(self):
        ret, out, _e = self.capture(self.mod.cmd_open, [])
        self.assertIsNone(ret)
        self.assertEqual([
            "[2026-03-01] mac:zuvo-plugin B-2        - | newest",
            "[2026-02-01] vps:zuvo-landing L-2   medium | landing",
            "[2026-01-01] mac:zuvo-plugin B-1     high | first",
            "[----------] vps:other O-1      low | undated",
            "",
            "(4 open, showing 4)",
        ], out.splitlines())

    def test_repo_filter_is_a_substring_match_and_is_named_in_the_footer(self):
        _r, out, _e = self.capture(self.mod.cmd_open, ["--repo", "zuvo"])
        self.assertEqual(["B-2", "L-2", "B-1"], [line.split()[2] for line in out.splitlines()[:3]])
        self.assertEqual("(3 open in zuvo, showing 3)", out.splitlines()[-1])

    def test_repo_filter_matching_nothing_reports_zero(self):
        _r, out, _e = self.capture(self.mod.cmd_open, ["--repo", "nope"])
        self.assertEqual(["", "(0 open in nope, showing 0)"], out.splitlines())

    def test_repo_without_a_value_returns_2_with_a_message_and_no_listing(self):
        ret, out, err = self.capture(self.mod.cmd_open, ["--repo"])
        self.assertEqual(2, ret)
        self.assertEqual("backlog open: --repo needs a value\n", err)
        self.assertEqual("", out)

    def test_more_than_60_shows_60_and_the_true_total(self):
        self.write_index([item("h", "r", f"B-{n}", added=f"2026-01-{n % 28 + 1:02d}") for n in range(61)])
        _r, out, _e = self.capture(self.mod.cmd_open, [])
        lines = out.splitlines()
        self.assertEqual(60, sum(1 for line in lines if line.startswith("[")))
        self.assertEqual("(61 open, showing 60)", lines[-1])

    def test_text_is_cut_to_110_characters(self):
        self.write_index([item("h", "r", "B-1", text="x" * 200)])
        _r, out, _e = self.capture(self.mod.cmd_open, [])
        self.assertTrue(out.splitlines()[0].endswith("| " + "x" * 110))

    def test_characterize_open_repo_without_value_process_exits_zero(self):
        # BUG-SCAN (cmd_open X1): cmd_open returns 2, but the dispatch drops the return value, so the
        # PROCESS exits 0 — a caller cannot tell the usage error from a listing.
        r = run_cli(self.tmp, "open", "--repo")
        self.assertEqual(0, r.returncode)
        self.assertEqual("backlog open: --repo needs a value\n", r.stderr)
        self.assertEqual("", r.stdout)


class CmdCritTests(BacklogTestCase):
    def test_open_critical_then_high_oldest_first_upper_cased(self):
        self.write_index([
            item("mac.local", "a", "H-NEW", "open", "high", "2026-05-01", "high new"),
            item("vps", "b", "C-NEW", "open", "critical", "2026-04-01", "crit new"),
            item("vps", "b", "H-OLD", "open", "high", "2026-01-01", "high old"),
            item("vps", "b", "C-OLD", "open", "critical", "2026-02-01", "crit old"),
            item("vps", "b", "C-DONE", "done", "critical", "2026-01-01", "closed"),
            item("vps", "b", "M-1", "open", "medium", "2026-01-01", "medium"),
            item("vps", "b", "N-1", "open", None, "2026-01-01", "none"),
        ])
        _r, out, _e = self.capture(self.mod.cmd_crit)
        self.assertEqual([
            "CRITICAL vps:b C-OLD | crit old",
            "CRITICAL vps:b C-NEW | crit new",
            "    HIGH vps:b H-OLD | high old",
            "    HIGH mac:a H-NEW | high new",
            "",
            "(4 critical/high open across the fleet, showing 4)",
        ], out.splitlines())

    def test_undated_sorts_first_within_its_severity(self):
        self.write_index([item("h", "r", "DATED", "open", "high", "2026-01-01"),
                          item("h", "r", "UNDATED", "open", "high", "")])
        _r, out, _e = self.capture(self.mod.cmd_crit)
        self.assertEqual(["UNDATED", "DATED"], [line.split()[2] for line in out.splitlines()[:2]])

    def test_nothing_critical_reports_zero(self):
        self.write_index([item("h", "r", "L-1", "open", "low")])
        _r, out, _e = self.capture(self.mod.cmd_crit)
        self.assertEqual(["", "(0 critical/high open across the fleet, showing 0)"], out.splitlines())


