class DispatchTests(BacklogTestCase):
    """`__main__`: the real file as a real process in a sandbox with no collector configured."""

    def setUp(self):
        super().setUp()
        self.write_index([item("mac.local", "zuvo", "B-1", "open", "critical", "2026-01-01", "flaky gate")],
                         meta={"hosts": {"mac.local": {}}, "strays": [{"host": "mac.local", "path": "/wt"}]})

    def test_no_argument_runs_ls(self):
        r = run_cli(self.tmp)
        self.assertEqual(0, r.returncode, r.stderr)
        self.assertIn("mac:zuvo", r.stdout)
        self.assertEqual("TOTAL open=1 done=0 across 1 repos / 1 hosts", r.stdout.splitlines()[-1])

    def test_unknown_command_exits_1_with_usage_on_stderr(self):
        r = run_cli(self.tmp, "nope")
        self.assertEqual(1, r.returncode)
        self.assertTrue(r.stderr.startswith("zuvo backlog — ONE place for every backlog in the fleet"))
        self.assertIn("~/.zuvo/backlog grep <text>       full-text search across every backlog", r.stderr)
        self.assertEqual("", r.stdout)

    def test_grep_without_text_exits_1_with_usage(self):
        r = run_cli(self.tmp, "grep")
        self.assertEqual(1, r.returncode)
        self.assertEqual("usage: backlog grep <text>\n", r.stderr)

    def test_each_view_command_routes_to_its_function(self):
        cases = {
            ("ls",): "TOTAL open=1",
            ("open",): "(1 open, showing 1)",
            ("open", "--repo", "zuvo"): "(1 open in zuvo, showing 1)",
            ("crit",): "(1 critical/high open across the fleet, showing 1)",
            ("grep", "FLAKY"): "(1 matches, showing 1)",
            ("strays",): "  mac: /wt",
        }
        for args, marker in cases.items():
            with self.subTest(args=args):
                r = run_cli(self.tmp, *args)
                self.assertEqual(0, r.returncode, r.stderr)
                self.assertIn(marker, r.stdout)

    def test_pull_and_sync_route_to_the_collector_and_name_the_missing_host(self):
        for cmd, what in (("pull", "pull the fleet index"), ("sync", "fetch the collector token")):
            with self.subTest(cmd=cmd):
                r = run_cli(self.tmp, cmd)
                self.assertEqual(1, r.returncode)
                self.assertEqual("backlog: no collector host configured (ZUVO_COLLECTOR_SSH or "
                                 f"~/.zuvo/collector.conf) — cannot {what}\n", r.stderr)

    def test_missing_index_names_the_script_path(self):
        os.remove(self.mod.INDEX)
        r = run_cli(self.tmp, "ls")
        self.assertEqual(1, r.returncode)
        self.assertIn("no index yet — run: ", r.stderr)
        self.assertIn("scripts/zuvo-home/backlog sync", r.stderr)


